SELECT "RELAUNCHED" AS "RELAUNCHED", "LONG_RUNNING" AS "LONG_RUNNING", COUNT(*) AS count 
FROM "default"."jobs" 
WHERE "@timestamp_date" >= TIMESTAMP '2026-03-25 00:00:00.000000' AND "@timestamp_date" < TIMESTAMP '2026-04-02 00:00:00.000000' AND "POOL" IS NULL AND "RELAUNCHED" = true GROUP BY "RELAUNCHED", "LONG_RUNNING" 
 LIMIT 100;